/// Returns true iff `n` is even.
pub fn is_even(n: u32) -> bool {
    n % 2 == 0
}

/// Executable version of the even check (here just forwards to `is_even`).
pub fn is_even_exec(n: u32) -> bool {
    is_even(n)
}

/// Returns true iff there exists at least one even number in `arr`.
/// If `arr` is empty, returns false.
pub fn is_product_even(arr: &Vec<u32>) -> bool {
    arr.iter().any(|&x| is_even_exec(x))
}

